// 每篇的职场延伸：核心视角、他人回避责任时的事/人、自己不想做时的事/人。
const workplaceGuides = {
  '始计篇':['先算条件，再接承诺','先列清任务目标、资源、期限与负责人，找出谁的承诺缺失。','用事实核对对方能承担的部分，不凭“应该会做”推断。','列出投入、收益与机会成本，再决定接、谈条件或拒绝。','向分配任务的人说明你能投入多少，要求一起确认取舍。'],
  '作战篇':['控制消耗，避免久拖','把反复催办造成的等待与返工量化，设一个明确的交付节点。','讨论拖延对团队的消耗，给对方一次提出阻碍的机会。','把任务切成短周期交付，先完成可复用的第一段。','说明长期占用会挤掉什么，商定结束条件和复盘时间。'],
  '谋攻篇':['优先解决目标分歧','先确认双方要交付的结果是否相同，再讨论责任归属。','私下问清对方顾虑，寻找无需公开争输赢的分工。','问自己是否讨厌做法而非目标，提出更省力的替代路径。','先争取对目标达成一致，再协商执行方式。'],
  '军形篇':['守住可控边界','写清自己负责的接口、验收标准和超期后的升级路径。','只承诺自己可控制的部分，不代替对方保证结果。','先把已有资源、权限和时间摆出来，再承诺交付。','坦诚能力边界，要求必要的资源或调整范围。'],
  '兵势篇':['借流程形成合力','把任务交接做成清单和固定检查点，减少对反复催促的依赖。','让团队规则承载压力，避免把冲突变成两个人互相指责。','给枯燥任务设置模板、批处理或共同协作的节奏。','提出流程改进，让安排者看到省时的具体做法。'],
  '虚实篇':['把力气用在关键处','找出真正卡住项目的那一项交付，先要求对方确认它。','不在无关细节上拉扯，围绕关键承诺谈。','区分必须完成和可以延后的部分，先攻最重要的一块。','带着优先级建议沟通，争取缩小非关键范围。'],
  '军争篇':['争取有利的协作顺序','先确认谁的交付是前置条件，按依赖顺序安排责任。','解释顺序调整是为了减少等待，不是把麻烦推给对方。','先完成能解锁下一步的任务，暂缓低影响的工作。','说明顺序改变对整体进度的好处，请负责人定优先级。'],
  '九变篇':['准备变通方案','给回避承诺的环节准备备选人、备选时间或降级交付。','请对方在可行方案中选一个，不把一次拒绝视为终局。','任务条件变化时，调整范围、做法或期限，不机械硬扛。','主动提出两种可交付方案，让负责人选择。'],
  '行军篇':['用可观察信号判断进度','看实际产出和阻塞记录，不只听“快好了”。','以样稿或里程碑讨论进展，减少对动机的猜测。','先交一小段可见成果，检验自己是否真的缺资源。','用具体进度沟通困难，避免一句“不想做”结束讨论。'],
  '地形篇':['认清环境与权限','弄清跨部门接口、审批链和可升级的负责人。','承认对方可能受制于权限，协商谁能拍板。','判断任务是否受权限或工具限制，先补齐条件。','说明环境限制及需要谁协助，别把结构问题说成个人态度。'],
  '九地篇':['按所处阶段调整动作','项目越临近交付，越要把责任、时间和应急替补写清。','根据对方所处压力和权限选择沟通方式。','早期可试做，临近截止则先交核心版本并同步风险。','告诉团队当前阶段需要什么决策与支持。'],
  '火攻篇':['高风险动作先算代价','要升级问题前，核对证据、影响和可能的连带后果。','避免借公开批评逼人担责；先给私下澄清机会。','遇到高压任务先辨别是否存在合规、安全或声誉风险。','风险较高时，走正式渠道确认，而不是靠情绪做决定。'],
  '用间篇':['补足可靠信息','交叉核对任务记录、负责人和真实进度，再决定是否升级。','直接向相关人确认事实，避免传播未经证实的评价。','问清任务背景与验收方的真实需求，再判断是否值得做。','把问题问给有决策权的人，避免凭转述接下模糊任务。'],
  '瞒天过海':['警惕惯性里的盲点','定期检查习以为常的交接步骤，找出无人签收的责任空档。','以核对流程的方式提问，避免突然给同事贴标签。','识别自己为何习惯性答应，停下来确认优先级。','说明以往默认做法造成的负担，邀请重新分工。'],
  '围魏救赵':['从依赖环节入手','对方不接任务时，先打通他依赖的审批、资料或上游决定。','问“什么条件齐备你能推进”，把对抗转成共同解题。','绕开最难开始的部分，先处理能解除阻力的前置工作。','向负责人申请必要资料或决定，缩小卡住的范围。'],
  '借刀杀人':['善用规则，避免借势伤人','用公开的分工表和验收规则确认责任，少靠私人施压。','引用共同规则而非拉第三方站队，保护协作关系。','用现成模板、流程和工具处理不喜欢的重复工作。','请主管按统一标准排优先级，避免私下互相推任务。'],
  '以逸待劳':['提前准备，减少被动催办','在节点前备好验收清单，等到可判断的交付点再跟进。','约定检查时间，减少高频催促带来的抵触。','把任务分配到精力较好的时段，先备素材再集中完成。','提出合理节奏和检查点，让别人看得到进展。'],
  '趁火打劫':['利用窗口，但守住公平','突发变化时迅速补上责任空档，同时把权限和资源说清。','不要利用对方失误逼其背锅；讨论如何恢复交付。','有空档时先做能带来价值的部分，再谈长期分工。','说明你愿意支援的边界和需要的支持。'],
  '声东击西':['改变讨论入口','若责任争议僵住，先讨论可验收的下一步，再回头确认归属。','从双方共同关心的结果切入，降低防御。','先做一项容易启动的小工作，带动困难任务。','提出小范围试做，让负责人看到可行性再谈全面接手。'],
  '无中生有':['把假设变成可检验事实','针对“我以为他会做”，立即补一份明确分工和确认记录。','避免凭印象指责，先请当事人核对自己的理解。','不让“这工作没意义”的猜测代替事实，问清使用场景。','用一个小样本验证价值，再商量是否继续投入。'],
  '暗度陈仓':['明面目标清楚，路径可调整','保持交付目标透明，同时换用更顺手的协作工具或顺序。','变化涉及他人责任时先告知，避免制造被绕过的感觉。','保留结果要求，选择更容易启动的实现路径。','提出替代做法并约定验收标准。'],
  '隔岸观火':['观察后再介入','先看争议是短暂误会还是持续无人负责，记录影响后再介入。','给双方澄清机会，避免在信息不足时选边。','先观察任务是否真紧急，确认时限后再调整手头工作。','需要延后时说明当前排期，请负责人判定轻重。'],
  '笑里藏刀':['核对承诺与实际行为','把口头“没问题”转为可检查的日期和交付物。','保持礼貌，也明确询问未完成时如何处理。','面对表面轻松、实际庞杂的任务，先估工时与依赖。','善意接受讨论，但不在条件不清时答应全部。'],
  '李代桃僵':['权衡代价，明确替代','若要临时顶替别人，写清替代范围、结束时间和交接责任。','帮助对方渡过难关，同时避免长期无偿兜底。','可以放弃低价值细节换取核心交付，但先算代价。','与负责人约定删减项，不让范围缩水变成隐性失约。'],
  '顺手牵羊':['抓住低成本改进','在已有会议或交接中顺手补上责任和时间确认。','用轻量确认减少尴尬，不把小事升级成指责。','把不想做的任务挂在现有流程后面，顺手完成第一步。','建议合并会议或批量处理，减少额外切换成本。'],
  '打草惊蛇':['先试探真实阻力','先请求一个小交付，看对方卡在能力、资源还是意愿。','用开放式问题探询，避免先公开施压。','先做十分钟试验，辨别自己是怕难还是确实缺条件。','展示试做结果，再具体提出支持请求。'],
  '借尸还魂':['复用旧资源','翻出旧项目的责任表或验收模板，恢复清晰分工。','以历史共识作讨论起点，确认是否仍适用。','复用已有材料和旧方案，减少从零开始的负担。','请负责人说明旧方法哪些能沿用，哪些需要更新。'],
  '调虎离山':['换环境再谈','在公开会议争不清时，改为小范围核对任务接口。','让对方脱离被围观的场景，更容易说明顾虑。','离开让你分心的环境，先单独完成一个最小交付。','建议换成短会或书面讨论，集中解决具体阻碍。'],
  '欲擒故纵':['给选择，保留边界','让对方在两个可行交付时间中选择，并确认最终责任。','不逼对方当场认错，给解释困难和重新承诺的空间。','允许自己先做小版本，不要求一开始就完成全部。','坦诚顾虑并提出可行版本，让负责人选择范围。'],
  '抛砖引玉':['先给示例再要承诺','先拿出一份半成品分工表，请对方补上他负责的部分。','用自己的示范降低对方开口的门槛。','先做粗糙样稿，换取明确反馈后再继续投入。','向负责人展示初稿，请对方指出最值得完善的部分。'],
  '擒贼擒王':['找到真正能决定的人','找出谁有权分配任务和调整截止时间，请其确认责任。','别反复向无权限同事施压，尊重其处境。','先找能决定优先级的人，避免同时讨好多个需求方。','把冲突任务列给决策者，请他明确取舍。'],
  '釜底抽薪':['消除反复拖延的根源','查清对方不交付背后的资料、权限或需求变更问题。','讨论阻碍而非性格，减少无效指责。','找出真正让你抗拒的原因：不清楚、太大或没有资源。','提出具体条件调整，解决根因后再承诺时间。'],
  '混水摸鱼':['在混乱中先厘清边界','事情越乱，越要写明每个人的任务、依赖和决定人。','澄清事实时保持中立，不把混乱当作追责机会。','混乱中先抓最确定的一小块，避免接下所有空白。','说明你当前负责的范围，请负责人分配剩余部分。'],
  '金蝉脱壳':['保留交接，退出无效负担','若必须转移责任，留下交接材料和明确接手人。','退出前解释原因与过渡安排，避免突然甩手。','确认任务已不符合目标时，建议停止或移交并说明成本。','坦诚退出理由和完成的部分，请负责人决定后续归属。'],
  '关门捉贼':['缩小范围，集中解决','把争议限定在一项交付，明确截止时间和验收人。','私下解决具体问题，避免扩大到对方整个人。','限定工作范围和时段，先完成一个闭环。','提出阶段性交付，让负责人验收后再扩展。'],
  '远交近攻':['先处理眼前关键协作','优先确认最近会影响交付的负责人，再处理远期分工。','维持其他合作关系，不把当前矛盾扩散。','先做截止更近、影响更大的工作，远期任务排队。','解释优先级依据，约定后续任务的启动时间。'],
  '假道伐虢':['借流程推进需先讲明目的','借用现有会议或审批确认责任时，提前写明议题与目的。','不要以别的名义让人接下额外责任，保持透明。','借助现有项目资源完成任务前，核对使用权限。','提出资源共享请求，并说明对原任务的影响。'],
  '偷梁换柱':['核对交付是否被悄悄替换','对照原验收标准检查新版本，记录变更和批准人。','先问替换原因，再讨论是否接受，避免直接指控。','想用更简方案替代原任务时，先说明取舍。','与负责人确认替代方案的验收标准和风险。'],
  '指桑骂槐':['把暗示改为明确沟通','明确指出哪项交付缺失及对后续的影响。','找当事人私下谈，避免借公开批评其他人施压。','不靠抱怨让人猜到你不想做，直说困难与选择。','用事实表达排期冲突，请负责人做决定。'],
  '假痴不癫':['先问清楚，再表态','遇到模糊的责任安排，先问清实际负责人和交付标准。','保持提问姿态，不急着争辩对方动机。','在要求不清时先问目的、权限和截止日期。','把关键疑问一次列出，获得答案再承诺。'],
  '上屋抽梯':['避免让人无路可退','安排任务时保留求助和调整期限的通道。','给对方说出困难的机会，避免逼出敷衍承诺。','接任务前确认资源和退出条件，避免陷入无法完成的承诺。','说明哪些条件缺失会触发重排，而非临时消失。'],
  '树上开花':['用可见成果建立信心','展示已完成的部分，让责任人确认下一步。','先认可真实贡献，再提出缺口，避免只盯失误。','把小成果做成可见样稿，让枯燥任务变得可推进。','用样稿争取反馈和必要资源。'],
  '反客为主':['主动建立协作节奏','主动发起责任确认、检查点和风险同步，推动项目回到轨道。','主动不等于夺权；先取得相关人的认可。','主动提出做法和排期，把被动接受变成可协商计划。','给负责人一个具体方案，请他确认优先级。'],
  '美人计':['区分吸引力与实际责任','别因对方态度好就忽略交付记录与验收标准。','欣赏优点也要清楚谈责任，不把关系当替代。','别因任务看起来有趣就忽略工时和机会成本。','以实际目标和资源沟通，不靠一时好感接下工作。'],
  '空城计':['信息不足时避免虚张声势','核实当前到底完成了什么，及时暴露风险并求援。','承认不确定性，比装作一切受控更能保住信任。','如果不会做，先交现状和问题清单，不假装已经掌握。','明确需要的指导或资源，约定下一次更新。'],
  '反间计':['防止信息差伤害合作','让责任与进度在共享记录中可核查，减少传话造成的误判。','直接找当事人确认，不传播猜测或挑拨。','不要因为不同人说法冲突就立刻接任务，先核对要求。','请需求方统一口径，再承诺交付。'],
  '苦肉计':['区分真实困难与无效牺牲','看到对方加班或诉苦，也要检查实际交付和所需支持。','同理困难，同时明确责任与边界。','不靠熬夜证明态度，先明确最小可交付成果。','如实说明困难与代价，争取调整范围或资源。'],
  '连环计':['看清一环带动多环的影响','把串联任务的每个负责人和依赖写清，避免一个失约拖垮全链。','讨论连带影响，不把单个失误无限放大。','拆解复杂任务的依赖顺序，先完成第一环。','向负责人指出关键依赖，请其决定如何保障。'],
  '走为上计':['及时退出不值得继续的局面','若屡次无法获得必要承诺，保留记录并申请调整分工或退出。','退出前完成必要交接，保持专业关系。','评估任务已失去价值或超出安全边界时，提出终止。','用目标、成本和风险解释停止理由，并给出交接方案。']
};
